lessons.oldStyles:
.launcher-wrap{max-width:760px;margin:36px auto 60px;padding:0 16px}
  .launcher{background:#fff;border:3px solid #111;border-radius:12px;padding:28px 30px;box-shadow:6px 6px 0 #111}
  .launcher h2{font-family:'Barlow Condensed',Arial Narrow,sans-serif;font-weight:900;text-transform:uppercase;font-size:36px;line-height:1;margin:0 0 10px}
  .launcher p{color:#444;margin-bottom:18px}
  .l-acts{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}
  .l-btn{font:700 17px 'Barlow',Arial,sans-serif;padding:11px 18px;border:3px solid #111;border-radius:8px;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;gap:8px;background:#fff;color:#111}
  .l-btn.main{background:var(--acc);color:#fff;border-color:#111}
  .l-btn:hover{transform:translateY(-1px)}
  .l-meta{font-size:14px;color:#666;margin-top:18px;padding-top:14px;border-top:1.5px solid #e2ddd0}
  .pbtn,#hdrPresent{display:none!important}

